 public bool HasWaitingPassenger(int index){
  if(index<0||index>=stops.Length)return false;
  if(current!=null&&trip.State==TripState.ToPickup&&current.pickup==index)return true;
  if(current!=null&&trip.State==TripState.OnTrip&&current.pickup==index||Time.time<cooldown[index])return false;
  if(trip.State==TripState.Idle)foreach(var o in offers)if(o!=null&&o.pickup==index)return true;
  return roadsideWaiting!=null&&index<roadsideWaiting.Length&&roadsideWaiting[index];
 }
 public void RefreshWaitingPassengers(){
  if(session.business==null||!session.law)return;
  if(roadsideWaiting==null||roadsideWaiting.Length!=stops.Length)System.Array.Resize(ref roadsideWaiting,stops.Length);
  string seed=WaitingSeed;double now=session.business.ledger.Elapsed;bool reset=seed!=waitingSeed;
  if(reset||now>=nextWaitingRefresh){if(reset){waitingSeed=seed;waitingGeneration=0;}else waitingGeneration++;nextWaitingRefresh=now+PassengerWaitingPolicy.RefreshSeconds;
   for(int i=0;i<stops.Length;i++)if(reset||Vector3.SqrMagnitude(stops[i].Passenger-session.taxi.transform.position)>90*90)roadsideWaiting[i]=PassengerWaitingPolicy.Present(waitingSeed,waitingGeneration,runtimeStopIds[i]);
  }
  for(int i=0;i<people.Length;i++)if(people[i])people[i].SetActive(HasWaitingPassenger(i));
