 public JobOffer[] OrdinaryCandidates(){var result=new System.Collections.Generic.List<JobOffer>();if(session.business==null||session.business.ledger==null||session.services==null||Catalog.Stops.Length<=Catalog.LegacyCount||nav.hd==null)return result.ToArray();var pickups=new System.Collections.Generic.List<int>();var distances=new float[stops.Length];for(int i=0;i<stops.Length;i++){distances[i]=DirectedDistance(nav.hd,session.taxi.transform.position,session.taxi.transform.forward,stops[i]);if(!float.IsInfinity(distances[i])&&Time.time>=cooldown[i])pickups.Add(i);}pickups.Sort((a,b)=>distances[a].CompareTo(distances[b]));if(pickups.Count>6)pickups.RemoveRange(6,pickups.Count-6);int extra=-1;float extraDistance=float.PositiveInfinity;for(int i=Catalog.LegacyCount;i<stops.Length;i++)if(Time.time>=cooldown[i]&&distances[i]<extraDistance){extra=i;extraDistance=distances[i];}if(extra>=0&&!pickups.Contains(extra))pickups.Add(extra);
