 void RemapSavedStops(PassengerJobsSnapshot s){if(s.stopIds==null)return;if(s.cooldown==null||s.cooldown.Length!=s.stopIds.Length||s.stops==null||s.stops.Length!=s.stopIds.Length)throw new System.ArgumentException("Invalid saved catalog");var indices=new int[s.stopIds.Length];for(int i=0;i<indices.Length;i++)indices[i]=runtimeStopIds.IndexOf(s.stopIds[i]);System.Func<int,int> pin=i=>{if(i<0||i>=indices.Length)throw new System.ArgumentException("Invalid saved stop index");if(indices[i]<0)indices[i]=PinSavedStop(s.stopIds[i],s.stops[i]);return indices[i];};if(s.current!=null){s.current.pickup=pin(s.current.pickup);s.current.drop=pin(s.current.drop);}if(s.passengerVia>=0)s.passengerVia=pin(s.passengerVia);if(s.request!=null&&s.request.proposal>=0)s.request.proposal=pin(s.request.proposal);foreach(var o in s.offers??new JobOffer[0])if(o!=null&& !ReferenceEquals(o,s.current)){int p=runtimeStopIds.IndexOf(o.pickupStopId),d=runtimeStopIds.IndexOf(o.dropStopId);o.pickup=p;o.drop=d;}if(s.offers!=null)for(int i=0;i<s.offers.Length;i++)if(s.offers[i]!=null&&(s.offers[i].pickup<0||s.offers[i].drop<0))s.offers[i]=null;var waits=new float[stops.Length];for(int i=0;i<indices.Length;i++)if(indices[i]>=0)waits[indices[i]]=s.cooldown[i];s.cooldown=waits;if(s.waitingCaptured){if(s.roadsideWaiting==null||s.roadsideWaiting.Length!=indices.Length)throw new System.ArgumentException("Invalid saved waiting population");var population=new bool[stops.Length];for(int k=0;k<population.Length;k++)population[k]=PassengerWaitingPolicy.Present(WaitingSeed,s.waitingGeneration,runtimeStopIds[k]);for(int k=0;k<indices.Length;k++)if(indices[k]>=0)population[indices[k]]=s.roadsideWaiting[k];s.roadsideWaiting=population;}s.previousPickup=s.previousPickup>=0&&s.previousPickup<indices.Length?indices[s.previousPickup]:-1;s.previousDrop=s.previousDrop>=0&&s.previousDrop<indices.Length?indices[s.previousDrop]:-1;}
 public string AcceptanceRejection(int index){if(index<0||index>=offers.Length||offers[index]==null)return "선택한 호출이 갱신되었습니다";if(Active)return "현재 승객 운송을 먼저 마쳐 주세요";if(AcceptanceLocked)return "청결 승차 거부 · 주유소에서 세차 후 다시 수락하세요";if(Time.timeScale==0)return "메뉴를 닫고 수락하세요";if(!session.business.CanAccept)return session.business.ledger.State!=BusinessState.Open?"영업 마감 중 · 신규 수락 불가":"피로 한계 또는 출발 준비 중";if(float.IsInfinity(offers[index].distance)||float.IsInfinity(PickupBudget(offers[index])))return "현재 방향에서 픽업 경로가 연결되지 않습니다";return "";}
