ntil-Time.time):0,changeApplied=passengerChangeApplied,deadlineNotice=deadlineNotice,cooldown=copy};}
 public void RestoreLive(PassengerJobsSnapshot s){if(s!=null){NormalizePresence(s);RemapSavedStops(s);}if(s==null||s.trip==null||s.offers==null||s.offers.Length!=3||s.cooldown==null||s.cooldown.Length!=stops.Length||s.completed<0||s.failed<0||s.balance<0)throw new System.ArgumentException("Invalid passenger session");System.Action<JobOffer> validate=o=>{if(o!=null&&(o.pickup<0||o.pickup>=stops.Length||o.drop<0||o.drop>=stops.Length||o.fare<0))throw new System.ArgumentException("Invalid saved stop");};validate(s.current);foreach(var o in s.offers)validate(o);trip.Restore(s.trip);if(Active&&s.current==null||trip.State==TripState.OnTrip&&s.drunk==null)throw new System.ArgumentException("Missing active passenger");previousPickup=s.previousPickup;previousDrop=s.previousDrop;current=s.current;offers=s.offers;OfferId=s.offerId;message=s.message;CareStatus=s.careStatus;if(s.drunk!=null)s.drunk.Validate();DrunkRide=s.drunk==null?null:s.drunk.Copy();if(trip.State==TripState.OnTrip&&DrunkRide!=null&&DrunkRide.Vomited)session.business.ledger.Care.MarkVomit();RequestReward=s.reward;if(s.boardingDrivingScore<0||s.boardingDrivingScore>100||s.comfortRecovered<0||s.comfortRecovered>4)throw new System.ArgumentException("Invalid saved driving fare/recovery");if(s.settlementPolicyVersion!=0&&s.settlementPolicyVersion!=4)throw new System.ArgumentException("Unsupported saved fare policy");SettlementPolicyVersion=s.settlementPolicyVersion;DrivingFareCaptured=s.drivingFareCaptured;BoardingDrivingScore=s.boardingDrivingScore;ComfortRecovered=s.comfortRecovered;InitialFare=s.initialFare>0?s.initialFare:current==null?0:current.fare;StartSatisfaction=s.startSatisfaction;StartDeficit=s.startDeficit;CleanBonus=s.cleanBonus;ReferenceSeconds=s.referenceSeconds;boardingDistance=s.boardingDistance;boardingCollisionEvents=s.boardingCollisionEvents;boardingRedEvents=s.boardingRedEvents;generation=s.generation;passengerVia=s.passengerVia;passengerChangeApplied=s.changeApplied;completed=s.completed;failed=s.failed;balance=s.balance;deadlineNotice=s.deadlineNotice;resultUntil=s.resultSeconds>0?Time.time+s.resultSeconds:0;for(int i=0;i<cooldown.Length;i++)cooldown[i]=Time.time+s.cooldown[i];if(s.navigationCaptured)nav.PreferFastest=s.navFastest;var restoringZones=GetComponent<ServiceLawZones>();if(restoringZones)restoringZones.PrepareForRestore();if(Active){SetGoal(trip.State==TripState.ToPickup?current.pickup:PassengerViaPending?passengerVia:current.drop);var zones=GetComponent<ServiceLawZones>();if(zones){if(trip.State==TripState.ToPickup)zones.BeginPickup(current);else if(!trip.ArrivalLocked)zones.BeginTrip(current);}}else{nav.Clear();marker.SetActive(false);}if(s.manners!=null)session.manners.RestoreLive(s.manners);if(s.request!=null&&session.requests)session.requests.RestoreLive(s.request);RestoreScenario(s);if(s.waitingCaptured){if(s.roadsideWaiting==null||s.roadsideWaiting.Length!=stops.Length||s.waitingGeneration<0||float.IsNaN(s.waitingRefreshSeconds)||s.waitingRefreshSeconds<0||s.waitingRefreshSeconds>PassengerWaitingPolicy.RefreshSeconds)throw new System.ArgumentException("Invalid waiting state");roadsideWaiting=(bool[])s.roadsideWaiting.Clone();waitingSeed=WaitingSeed;waitingGeneration=s.waitingGeneration;nextWaitingRefresh=session.business.ledger.Elapsed+s.waitingRefreshSeconds;}else waitingSeed="";RefreshWaitingPassengers();}
