 JobOffer Make(int pickup,int drop,PrototypeScenario scenario=null){float distance=nav.Distance(stops[pickup],stops[drop]);var offer=new JobOffer{pickup=pickup,drop=drop,requiredScore=new[]{60,70,85}[(pickup+drop)%3],distance=distance};var zones=GetComponent<ServiceLawZones>();if(zones){if(scenario!=null){if(!zones.ConfigureScenario(offer,scenario))return null;}else zones.ConfigureOffer(offer);}offer.fare=3000+Mathf.CeilToInt(offer.distance*4/100)*100;offer.seconds=Mathf.Max(120,Mathf.Ceil(offer.distance/4+90+offer.waitSeconds));Stamp(offer);return offer;}
 public void ResetOffers(){generation=0;Generate();}
 public void Generate(){nextOfferRetry=Time.time+3;if(stops.Length<2)return;var zones=GetComponent<ServiceLawZones>();if(session.business!=null&&session.business.ledger!=null&&session.business.ledger.OneDay&&zones&&zones.Ready){var candidates=new System.Collections.Generic.List<JobOffer>();foreach(var course in zones.scenarios){var offer=Make(course.pickup,course.drop,course);if(offer!=null)candidates.Add(offer);}double elapsed=session.business.ledger.Elapsed;offerPhase=elapsed<300?0:elapsed<900?1:2;var ranks=new System.Collections.Generic.Dictionary<JobOffer,float>();foreach(var candidate in candidates)ranks[candidate]=OfferRank(candidate,elapsed);candidates.RemoveAll(o=>float.IsInfinity(ranks[o]));candidates.Sort((a,b)=>ranks[a].CompareTo(ranks[b]));for(int i=0;i<3;i++)offers[i]=i<candidates.Count?candidates[i]:null;MixOrdinaryOffers();generation++;return;}for(int i=0;i<3;i++){offers[i]=null;
  if(zones&&zones.Ready&&zones.scenarios.Count>0)for(int k=0;k<zones.scenarios.Count;k++){var scenario=zones.scenarios[(generation+i+k)%zones.scenarios.Count];bool duplicate=false;for(int j=0;j<i;j++)if(offers[j]!=null&&offers[j].scenarioId==scenario.id)duplicate=true;if(duplicate)continue;var candidate=Make(scenario.pickup,scenario.drop,scenario);if(candidate!=null){offers[i]=candidate;break;}}
  if(offers[i]==null){int p=(generation+i*2)%stops.Length,d=(p+3+i)%stops.Length;if(p==d)d=(d+1)%stops.Length;offers[i]=Make(p,d);}
 }MixOrdinaryOffers();generation++;} public bool Accept(int index){PrepareForNextCall();string rejection=AcceptanceRejection(index);if(rejection!=""){message=rejection;return false;}if(trip.State!=TripState.Idle)return false;current=offers[index];InitialFare=current.fare;Stamp(current);if(float.IsInfinity(current.distance))return false;float pickup=PickupBudget(current);if(float.IsInfinity(pickup)||!trip.Accept(current.fare,current.seconds,pickup))return false;OfferId=session.law?session.law.ids.Next("offer"):"offer";if(session.law)session.law.tripId=OfferId;message="호출 수락 · 픽업 장소: "+KoreanText.Stop(stops[current.pickup].name);SetGoal(current.pickup);RefreshWaitingPassengers();var zones=GetComponent<ServiceLawZones>();if(zones)zones.BeginPickup(current);session.business.SaveCheckpoint();return true;}
 public static float DirectedDistance(HdRoadGraph graph,Vector3 position,Vector3 direction,MapStop goal){
  if(graph==null)return Vector3.Distance(position,goal.Kerb);
  float at;int start=graph.Nearest(position,direction,out at);
  if(start==goal.laneEdge&&Mathf.Abs(at-goal.laneAt)<.25f)return 0;
  var route=graph.Route(start,at,goal.laneEdge,goal.laneAt);return route==null?float.PositiveInfinity:route.path.length;
 }
 float OfferRank(JobOffer o,double elapsed){if(Time.time<cooldown[o.pickup])return float.PositiveInfinity;float pickup=DirectedDistance(nav.hd,session.taxi.transform.position,session.taxi.transform.forward,stops[o.pickup]);float meal=0;if(elapsed>=300&&elapsed<900){var drop=stops[o.drop];meal=DirectedDistance(nav.hd,drop.Kerb,drop.Direction,session.services.MealStop);}int id=0;int.TryParse(o.scenarioId.Replace("PS",""),out id);return OneDayOfferPolicy.Rank(o.distance,pickup,meal,elapsed,id,generation);}
 public void ResumePickupNavigation(){if(trip.State==TripState.ToPickup&&current!=null)SetGoal(current.pickup);}
 public void AdvancePickupWait(float seconds){if(trip.State!=TripState.ToPickup)return;trip.Tick(seconds);if(trip.PickupExpired){message="승객 대기 시간 초과 · 호출 취소 / 요금 없음";Finish();if(session.law)session.law.tripId="";}}
 void SetGoal(int index){nav.SetDestination(stops[index]);marker.transform.rotation=Quaternion.LookRotation(stops[index].Direction);marker.SetActive(true);marker.transform.position=stops[index].Kerb+Vector3.up*.085f;}
 public bool At(int index){return stops[index].CanStop(session.taxi.transform.position,session.taxi.transform.forward,session.taxi.body.velocity.magnitude);}
 float PickupBudget(JobOffer offer){
  return OneDayOfferPolicy.PickupSeconds(DirectedDistance(nav.hd,session.taxi.transform.position,session.taxi.transform.forward,stops[offer.pickup]));
 }
 public bool PreviewPassengerChange(int stop,bool via,out float extraDistance,out int newFare,out float newRemaining){
  extraDistance=0;newFare=trip.Fare;newRemaining=trip.Remaining;
  if(trip.State!=TripState.OnTrip||trip.ArrivalLocked||current==null||passengerChangeApplied||PassengerViaPending||trip.Remaining<=0||stop<0||stop>=stops.Length||stop==current.drop||nav.hd==null||session.taxi.body.velocity.magnitude>=.56f)return false;
  var zones=GetComponent<ServiceLawZones>();var course=GetComponent<ScenarioChoiceSituation>();if(zones&&zones.Live&&zones.Live.Active||course&&(course.Open||course.ActiveObservation))return false;
  float at;int start=nav.hd.Nearest(session.taxi.transform.position,session.taxi.transform.forward,out at);var goal=stops[current.drop];var target=stops[stop];
  var old=nav.hd.Route(start,at,goal.laneEdge,goal.laneAt);var changed=nav.hd.Route(start,at,target.laneEdge,target.laneAt);if(old==null||changed==null)return false;
  float distance=changed.path.length;if(via){var onward=nav.hd.Route(target.laneEdge,target.laneAt,goal.laneEdge,goal.laneAt);if(onward==null)return false;distance+=onward.path.length;}
  extraDistance=Mathf.Max(0,distance-old.path.length);newFare=trip.Fare+Mathf.CeilToInt(extraDistance*4/100)*100;newRemaining=trip.Remaining+extraDistance/4+30;return true;
 }
 public bool TryChangeDestination(int stop){return ApplyPassengerChange(stop,false);}
 public bool TrySetPassengerVia(int stop){return ApplyPassengerChange(stop,true);}
 bool ApplyPassengerChange(int stop,bool via){float extra,remaining;int fare;float priorRemaining=trip.Remaining;if(!PreviewPassengerChange(stop,via,out extra,out fare,out remaining)||!trip.Revise(fare,remaining))return false;passengerChangeApplied=true;if(via)passengerVia=stop;else current.drop=stop;Stamp(current);current.fare=fare;current.seconds+=remaining-priorRemaining;current.distance+=extra;SetGoal(stop);message=via?"승객 경유 요청 수락 · 경유 장소에서 정차 후 F":"승객 목적지 변경 수락 · 새 목적지로 안내합니다";return true;}
System.Collections.Generic.Dictionary<JobOffer,float> fuelCache=new System.Collections.Generic.Dictionary<JobOffer,float>();float fuelCacheUntil;
 public float EstimatedFuel(JobOffer offer){if(offer==null)return float.PositiveInfinity;if(Time.unscaledTime>=fuelCacheUntil){fuelCache.Clear();fuelCacheUntil=Time.unscaledTime+1;}float cached;if(fuelCache.TryGetValue(offer,out cached))return cached;float pickup;
  if(nav.hd==null)pickup=Vector3.Distance(session.taxi.transform.position,stops[offer.pickup].Kerb);else {float at;int edge=nav.hd.Nearest(session.taxi.transform.position,session.taxi.transform.forward,out at);var goal=stops[offer.pickup];var route=nav.hd.Route(edge,at,goal.laneEdge,goal.laneAt);pickup=edge==goal.laneEdge&&Mathf.Abs(at-goal.laneAt)<.25f?0:route==null?float.PositiveInfinity:route.path.length;}
  var settings=session.business.settings;float need=(pickup+offer.distance)/1000*settings.fuelPerKm+(pickup/4+offer.seconds)/60*settings.idlePerMinute;fuelCache[offer]=need;return need;
 }
 public string FuelHint(JobOffer offer){float need=EstimatedFuel(offer);if(float.IsInfinity(need))return "연료 예측: 픽업 경로 확인 필요";float fuel=session.business.ledger.Account.Fuel;if(session.business.ledger.OneDay){var predicted=session.business.ledger.Driver.Copy();float seconds=(offer.distance+Vector3.Distance(session.taxi.transform.position,stops[offer.pickup].Kerb))/8+offer.waitSeconds;predicted.Advance(seconds);return "예상 연료 "+need.ToString("0.0")+"% · "+(fuel<need?"주유 권장 · ":"")+"운송 후 피로 약 "+predicted.fatigue.ToString("0")+" (교통에 따라 변동)"+(seconds>session.business.ledger.SecondsLeft?" · 마감 넘길 수 있음":"");}return "예상 연료 "+need.ToString("0.0")+"% · "+(fuel<need?"부족 예상 · 먼저 주유 권장":fuel<need+5?"도착 후 잔량 적음":"현재 잔량으로 운행 예상")+" (대기·우회에 따라 변동)";}
 public bool Interact(){if(Time.timeScale==0)return false;PrepareForNextCall();
  if(trip.State==TripState.Idle){if(!session.business.CanAccept){message="지금은 새 승객을 태울 수 없습니다";return false;}int closest=-1;float best=8;for(int i=0;i<stops.Length;i++)if(HasWaitingPassenger(i)&&At(i)){float d=Vector3.Distance(session.taxi.transform.position,stops[i].Kerb);if(d<best){best=d;closest=i;}}
   if(closest<0){message="손님이 있는 오른쪽 연석에 같은 방향으로 정차하세요 (시속 2km 미만)";return false;}
   current=null;var roadsideZones=GetComponent<ServiceLawZones>();if(roadsideZones&&roadsideZones.Ready)foreach(var course in roadsideZones.scenarios)if(!course.beforePickup&&course.pickup==closest){current=Make(course.pickup,course.drop,course);if(current!=null)break;}if(current==null)current=Make(closest,(closest+3+completed*7)%stops.Length==closest?(closest+1)%stops.Length:(closest+3+completed*7)%stops.Length);if(float.IsInfinity(current.distance))return false;trip.Accept(current.fare,current.seconds);InitialFare=current.fare;OfferId="";return Board();
  }
  if(trip.State==TripState.ToPickup){if(!session.business.CanAccept)return false;if(!At(current.pickup)){message="승차 지점 오른쪽 연석에 화살표 방향으로 정차 후 F";return false;}return Board();}
  if(trip.State==TripState.OnTrip){if(PassengerViaPending){if(!At(passengerVia)){message="부탁한 경유 장소의 오른쪽 연석에 정차 후 F";return false;}session.signals.BeginPassengerStop();passengerVia=-1;SetGoal(current.drop);message="경유 완료 · 최종 목적지로 출발하세요";return true;}if(!At(current.drop)){message="목적지 오른쪽 연석에 화살표 방향으로 정차 후 F";return false;}
   if(!trip.ArrivalLocked){if(DrunkRide.Vomited)session.business.ledger.Care.MarkVomit();trip.LockArrival();DrunkRide.Arrive(trip.ArrivedOnTime);var zones=GetComponent<ServiceLawZones>();if(zones)zones.RecordSkippedDelivery();session.signals.BeginPassengerStop();if(session.requests)session.requests.Finish();bool unsafeDriving=session.manners.collisionEvents>boardingCollisionEvents||session.manners.redEvents>boardingRedEvents||session.requests&&!session.requests.LawClear;
    RequestReward=DrivingFareCaptured&&SettlementPolicyVersion>=4?PassengerReward.CalculateCurrentFare(session.manners.ledger.Score,current.requiredScore,trip.Fare,session.requests?session.requests.TotalSatisfactionDelta:0,trip.ArrivedOnTime,StartSatisfaction,CleanBonus,ReferenceSeconds,DrunkRide.ArrivalElapsed,unsafeDriving,BoardingDrivingScore,ComfortRecovered):DrivingFareCaptured?PassengerReward.CalculateWithDrivingScore(session.manners.ledger.Score,current.requiredScore,trip.Fare,session.requests?session.requests.TotalSatisfactionDelta:0,trip.ArrivedOnTime,StartSatisfaction,CleanBonus,ReferenceSeconds,DrunkRide.ArrivalElapsed,unsafeDriving,BoardingDrivingScore,ComfortRecovered):PassengerReward.CalculateDetailed(session.manners.ledger.Score,current.requiredScore,trip.Fare,0,session.requests?session.requests.TotalSatisfactionDelta:0,trip.ArrivedOnTime,StartSatisfaction,CleanBonus,ReferenceSeconds,DrunkRide.ArrivalElapsed,unsafeDriving,ComfortRecovered);RequestReward.startDeficit=StartDeficit;
    if(DrunkRide.Waiting){ShowWakeWait();session.business.SaveCheckpoint();return true;}}
   if(!DrunkRide.CanDisembark(true,true)){ShowWakeWait();return true;}return CompleteDelivery(true);}
  return false;
 }
 bool Board(){Stamp(current);var care=session.business.ledger.Care;if(care.NeedsWash){string refusal=string.IsNullOrEmpty(OfferId)?session.law.ids.Next("roadside-refusal"):OfferId;care.Refuse(refusal);cooldown[current.pickup]=Time.time+60;trip.Clear();if(session.law)session.law.tripId="";message="손님  “차가 너무 더러워서 못 타겠어요.” · F7 주유소에서 세차해 주세요";CareStatus=message;Finish();session.business.SaveCheckpoint();return false;}if(!trip.Board())return false;SettlementPolicyVersion=4;DrivingFareCaptured=true;BoardingDrivingScore=session.law.ledger.TotalScore;ComfortRecovered=0;session.signals.BeginPassengerStop();RequestReward=null;passengerChangeApplied=false;string candidate=current.candidateSeed;if(session.law){session.law.tripId=session.law.ids.Next("trip");if(!string.IsNullOrEmpty(OfferId)){var link=new LawEvent{recoveryPolicyVersion=1,id=session.law.ids.Next("boarding"),tripId=session.law.tripId,day=session.law.Day,family="호출 연결",scenario=current.scenarioId,occupied=true,reason="수락 호출 "+OfferId+" → 탑승 운송 "+session.law.tripId};link.Add("호출 연결",LawVerdict.NoOpportunity,0);session.law.ledger.Record(link);}}DrunkRide=DrunkRideState.Create(candidate,care.DrunksBoarded<1,ForcedRideCase);if(DrunkRide.IsDrunk)care.BoardDrunk();StartDeficit=PassengerReward.Deficit(candidate);CleanBonus=care.BoardingBonus;StartSatisfaction=current.requiredScore-StartDeficit+CleanBonus;session.manners.BeginRide();boardingCollisionEvents=session.manners.collisionEvents;boardingRedEvents=session.manners.redEvents;cooldown[current.pickup]=Time.time+60;people[current.pickup].SetActive(false);SetGoal(current.drop);ReferenceSeconds=nav.estimatedSeconds;boardingDistance=Mathf.Max(1,nav.remaining);message="승객 탑승 · 시작 만족도 "+StartSatisfaction+" / 요구 "+current.requiredScore+" (청결 +"+CleanBonus+") · 목적지: "+KoreanText.Stop(stops[current.drop].name)+"\n"+FareAgreementText(current.fare);session.manners.lastEvent="운전 만족도 M 100 · 시작 승객 만족도 "+StartSatisfaction+" / 요구 "+current.requiredScore;CareStatus=DrunkRide.IsDrunk?"취객 탑승 · 조금 취했네요. 목적지까지 부탁해요.":"";if(DrunkRide.IsDrunk)message+="\n"+CareStatus;var zones=GetComponent<ServiceLawZones>();if(zones)zones.BeginTrip(current);if(session.requests)session.requests.Begin();RefreshWaitingPassengers();session.business.SaveCheckpoint();return true;}
 void ShowWakeWait(){CareStatus="도착 완료 · 손님이 일어나지 않습니다 · "+Mathf.FloorToInt(DrunkRide.WaitElapsed)+"초 대기 · "+(DrunkRide.WaitElapsed<15?Mathf.CeilToInt(DrunkRide.WaitUntilWake)+"초 뒤 F 다시 깨우기":"F 다시 깨우기")+" / 30초 자동 하차 · 안전 정차 유지";message=CareStatus;}
 bool CompleteDelivery(bool wake){if(DrunkRide==null||!DrunkRide.Disembark(At(current.drop),wake))return false;if(!HasWaitingPassenger(current.drop))cooldown[current.drop]=Mathf.Max(cooldown[current.drop],Time.time+90);previousPickup=current.pickup;previousDrop=current.drop;int pay=trip.Complete();session.business.ledger.Care.Finish(session.law.tripId,DrunkRide.Vomited);pay=RequestReward.Total;if(trip.State==TripState.Failed){failed++;session.business.RecordPassenger(0,"시간 초과 후 목적지 도착");session.business.RecordFailure();message="늦은 도착 · 승객 하차 완료 / 요금 0원\n"+RequestReward.Summary;}else{balance+=pay;completed++;session.business.RecordFare(pay);session.business.RecordPassenger(pay,"운송 완료");message=RequestReward.Summary;}CareStatus=(DrunkRide.Vomited?"구토 후 청결 저하 · ":"")+"하차 후 청결 "+Cleanliness+"/100";message+="\n"+CareStatus;Finish();session.business.SaveCheckpoint();return true;}
 public void ClearForDay(){SettlementPolicyVersion=0;DrivingFareCaptured=false;BoardingDrivingScore=ComfortRecovered=0;RequestReward=null;InitialFare=0;waitingSeed="";var zones=GetComponent<ServiceLawZones>();if(zones)zones.EndTrip();if(session.law)session.law.tripId="";trip.Clear();DrunkRide=null;CareStatus="";current=null;passengerVia=-1;passengerChangeApplied=false;OfferId="";resultUntil=0;deadlineNotice=false;nav.Clear();marker.SetActive(false);for(int i=0;i<cooldown.Length;i++)cooldown[i]=0;Generate();message="1·2·3으로 호출 선택 / 길가 손님 옆에 정차 후 F";}
