 void UpdateCare(){if(trip.State!=TripState.OnTrip||DrunkRide==null||Time.deltaTime<=0)return;float progress=Mathf.Clamp01(1-nav.remaining/boardingDistance);bool warned=DrunkRide.Warned;bool vomited=DrunkRide.Advance(Time.deltaTime,progress);if(DrunkRide.Vomited)session.business.ledger.Care.MarkVomit();bool dialogue=DrunkRide.UpdateDialogue(session.requests&&session.requests.SuppressFollowupDialogue);if(vomited||warned!=DrunkRide.Warned||dialogue){CareStatus=DrunkRide.VisibleDialogue(session.requests&&session.requests.SuppressFollowupDialogue);if(CareStatus.Length>0)message=CareStatus;session.business.SaveCheckpoint();}if(!DrunkRide.Waiting)return;if(DrunkRide.WaitElapsed>=30&&At(current.drop)){CompleteDelivery(false);return;}ShowWakeWait();if(!At(current.drop)){CareStatus="도착 기록 유지 · 안전한 목적지 정차 구역으로 돌아오세요 · 자동 하차 대기";message=CareStatus;}}
