 void Update(){UpdateCare();if(session.business.ledger.OneDay&&trip.State==TripState.Idle){double elapsed=session.business.ledger.Elapsed;int phase=elapsed<300?0:elapsed<900?1:2;if(phase!=offerPhase||offers[0]==null&&Time.time>=nextOfferRetry)Generate();}trip.Tick(Time.deltaTime);if(trip.PickupExpired&&resultUntil==0){message="승객 대기 시간 초과 · 호출 취소 / 요금 없음";Finish();if(session.law)session.law.tripId="";}RecordExpiredTrip();
